import random, string, re

class RobotFixed:
    _used = set()
    _letters = string.ascii_uppercase
    _digits = string.digits

    def __init__(self):
        self._name = None

    @property
    def name(self):
        if self._name is None:
            self._name = self._allocate()
        return self._name

    def reset(self):
        self._name = None

    @classmethod
    def _candidate(cls):
        return (
            random.choice(cls._letters)
            + random.choice(cls._letters)
            + random.choice(cls._digits)
            + random.choice(cls._digits)
            + random.choice(cls._digits)
        )

    @classmethod
    def _allocate(cls):
        while True:
            candidate = cls._candidate()
            if candidate not in cls._used:
                cls._used.add(candidate)
                return candidate

name_re = r"^[A-Z]{2}\d{3}$"
for s in [0, 1, 42, 1234, 99999]:
    RobotFixed._used.clear()
    random.seed(s)
    r = RobotFixed()
    n1 = r.name
    r.reset()
    n2 = r.name
    assert n1 != n2
    assert re.match(name_re, n2)

    random.seed(s)
    r.reset()
    n3 = r.name
    assert n1 != n3, f"Seed {s}: n1 ({n1}) == n3 ({n3})"
    assert n2 != n3, f"Seed {s}: n2 ({n2}) == n3 ({n3})"
print("All seeds passed with RobotFixed!")
'
